def describe_civilization_intelligence() -> str:
    lines = ["TitanAI Civilization Intelligence Layer", "", "This layer represents TitanAI as a civilization-scale intelligence coordination system for knowledge, engineering, business, education, and personal capability.", ""]
    for capability in CIVILIZATION_CAPABILITIES:
        lines.append(f"- {capability.name} [{capability.category}]")
        lines.append(f"  {capability.purpose}")
    return "\n".join(lines)
